function prev(a, i) { return jump(a, i, -1); }

function escRe(s) { return String(s).replace(/[$^*+?.()|[\]{}\\]/g, '\\$&'); }

function flags(src, i, n) { while (i < n && /[a-z]/.test(src[i])) i++; return i; }

